package cn.xi.cloudwidget;

import android.content.*;
import android.graphics.*;
import android.util.AtomicFile;
import android.net.Uri;
import android.provider.DocumentsContract;
import org.json.*;
import java.io.*;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.zip.*;

/** Local ZIP interchange. Validation never mutates saved data. Publish is one prefs commit. */
final class Backup {
    static final long MAX_TOTAL=256L*1024*1024,MAX_IMAGE=24L*1024*1024;
    static final int MAX_FILES=2048,MAX_CARDS=500;
    static final String APP="cn.xi.cloudwidget",RECEIPT="backup-receipt:",MARKER="backup-transaction";
    private static Set<String> pendingPaths=new HashSet<>();
    private static final Object EXPORT_LOCK=new Object();
    interface Fault {void at(String phase)throws IOException;}
    static final Fault NONE=phase->{};
    static class Plan implements Closeable {
        File stage;JSONObject meta;JSONArray cards;Map<String,File> files=new TreeMap<>();String digest;boolean duplicate;
        int photos,pngs,packs,conflicts,fontFallbackCards;
        public String summary(){return (fontFallbackCards>0?"思源宋体已移除，将使用系统默认（"+fontFallbackCards+" 张卡片）。\n\n":"")+"来源：云朵小卡 "+meta.optString("appVersion")+"\n创建："+meta.optString("createdAt")+"\n卡片 "+cards.length()+" · 照片 "+photos+" · PNG "+pngs+" · 素材包 "+packs+"\n同 ID 卡片冲突 "+conflicts+" 张：将另存新 ID，保留事项 ID 和历史。\n相同文件去重；素材包冲突另存并改写本次引用。\n现有卡片及桌面绑定保持原样；恢复后需重新添加到桌面。";}
        public void close(){if(stage!=null)remove(stage);}
    }
    static SharedPreferences prefs(Context c){return c.getSharedPreferences("cards-v1",0);}
    static String hash(InputStream input)throws IOException{try{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] block=new byte[32768];int n;while((n=input.read(block))!=-1)md.update(block,0,n);StringBuilder out=new StringBuilder();for(byte b:md.digest())out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    static String hash(File file)throws IOException{try(InputStream input=new FileInputStream(file)){return hash(input);}}
    static byte[] bytes(File file,long max)throws IOException{try(InputStream in=new FileInputStream(file)){return AssetStore.limited(in,max);}}
    static void write(File file,byte[] value)throws IOException{File parent=file.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("无法创建备份临时目录");try(FileOutputStream out=new FileOutputStream(file)){out.write(value);out.getFD().sync();}}
    static void json(File file,Object value)throws IOException{write(file,value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    static void remove(File root){File[] children=root.listFiles();if(children!=null)for(File child:children)remove(child);root.delete();}
    static File temp(Context c)throws IOException{File root=new File(c.getCacheDir(),"backups");if(!root.isDirectory()&&!root.mkdirs())throw new IOException("无法创建备份目录");File stage=new File(root,UUID.randomUUID().toString());if(!stage.mkdir())throw new IOException("存储空间不足");return stage;}
    static String safe(String path)throws IOException{
        AssetStore.safePath(path);
        if(!path.equals("backup.json")&&!path.equals("cards.json")&&!path.matches("photos/[A-Za-z0-9._-]+\\.png")&&!path.matches("stickers/[a-f0-9]{64}\\.png")&&!path.matches("assetpacks/[a-f0-9]{64}/[A-Za-z0-9._/-]+"))throw new IOException("备份中包含不支持的文件路径");
        return path;
    }
    static File local(Context c,String path)throws IOException{safe(path);File root=c.getFilesDir(),target=new File(root,path);if(!target.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator))throw new IOException("备份路径越界");return target;}
    static JSONObject parse(File file,int max)throws IOException{try{return new JSONObject(new String(bytes(file,max),java.nio.charset.StandardCharsets.UTF_8));}catch(JSONException e){throw new IOException("备份 JSON 损坏",e);}}
    static void require(boolean value,String message)throws IOException{if(!value)throw new IOException(message);}
    static String str(JSONObject value,String key,int max,boolean empty)throws IOException{Object raw=value.opt(key);require(raw instanceof String,"卡片字段类型错误："+key);String s=(String)raw;require(s.length()<=max&&(empty||!s.isEmpty()),"卡片字段长度错误："+key);return s;}
    static int integer(JSONObject j,String key,int min,int max)throws IOException{Object value=j.opt(key);require(value instanceof Number,"卡片数值类型错误："+key);double number=((Number)value).doubleValue();require(Double.isFinite(number)&&number==Math.floor(number)&&number>=min&&number<=max,"卡片数值超出范围："+key);return (int)number;}
    static void validateCard(JSONObject card)throws Exception{
        int schema=integer(card,"schema",3,4);require(str(card,"id",80,false).matches("[A-Za-z0-9._-]+"),"卡片 ID 无效");integer(card,"type",0,5);integer(card,"shape",0,2);integer(card,"font",0,FontCatalog.FILES.length-1);integer(card,"bgMode",0,3);integer(card,"border",0,Borders.NAMES.length-1);integer(card,"corner",0,30);integer(card,"size",14,26);integer(card,"padding",0,30);integer(card,"crop",0,3);integer(card,"opacity",0,100);
        for(String color:new String[]{"ink","background","borderInk"})integer(card,color,Integer.MIN_VALUE,Integer.MAX_VALUE);
        double stroke=card.getDouble("borderWidth");require(Double.isFinite(stroke)&&stroke>=.5&&stroke<=3,"边框粗细无效");require(card.opt("grid") instanceof Boolean,"格纹字段无效");str(card,"title",60,true);str(card,"body",400,true);LocalDate.parse(str(card,"date",10,false));
        for(String key:new String[]{"photo","backgroundPhoto"}){String name=str(card,key,120,true);require(name.isEmpty()||name.matches("[A-Za-z0-9._-]+\\.png"),"照片路径无效");}
        str(card,"backgroundAsset",240,true);JSONArray stickers=card.getJSONArray("stickers");require(stickers.length()<=3,"贴纸过多");for(int n=0;n<stickers.length();n++){JSONObject s=stickers.getJSONObject(n);str(s,"asset",240,false);for(String key:new String[]{"x","y","width"}){double v=s.getDouble(key);require(Double.isFinite(v)&&v>=(key.equals("width")?.08:0)&&v<=(key.equals("width")?.9:1),"贴纸坐标无效");}}
        JSONArray items=card.getJSONArray("items"),ids=card.getJSONArray("itemIds");require(items.length()==3&&ids.length()==3,"事项数量无效");Set<String> unique=new HashSet<>();for(int n=0;n<3;n++){require(items.get(n) instanceof String&&items.getString(n).length()<=60,"事项文字无效");require(ids.get(n) instanceof String,"事项 ID 类型无效");String id=ids.getString(n);require(id.length()>0&&id.length()<=80&&unique.add(id),"事项 ID 无效");}
        JSONObject history=card.getJSONObject("history");require(history.length()<=36600,"历史记录过多");Iterator<String> dates=history.keys();while(dates.hasNext()){String day=dates.next();LocalDate.parse(day);JSONObject daily=history.getJSONObject(day);require(daily.length()<=100,"每日事项记录过多");Iterator<String> keys=daily.keys();while(keys.hasNext()){String id=keys.next();require(id.length()>0&&id.length()<=80&&daily.get(id) instanceof Boolean,"历史记录内容无效");}}
    }
    static void validateWater(JSONObject card)throws Exception{
        if(card.getInt("schema")==3){require(card.getInt("type")!=5&&!card.has("waterHistory")&&!card.has("waterGoalMl")&&!card.has("waterQuickMl"),"旧格式含未知喝水字段");return;}
        integer(card,"waterGoalMl",100,10000);integer(card,"waterQuickMl",1,3000);require(card.getInt("type")!=5||card.getInt("shape")!=2,"今日喝水不支持 1×1");JSONObject history=card.getJSONObject("waterHistory");require(history.length()<=36600,"饮水历史过多");Iterator<String> days=history.keys();while(days.hasNext()){String day=days.next();require(day.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"),"饮水日期无效");LocalDate.parse(day);JSONArray entries=history.getJSONArray(day);require(entries.length()>0&&entries.length()<=1000,"饮水记录数量无效");for(int n=0;n<entries.length();n++){JSONObject entry=entries.getJSONObject(n);integer(entry,"ml",1,3000);Object at=entry.opt("at");require(at instanceof Number,"饮水时间戳类型无效");double stamp=((Number)at).doubleValue();require(Double.isFinite(stamp)&&stamp==Math.floor(stamp)&&stamp>=0&&stamp<=253402300799999L,"饮水时间戳无效");}}
    }
    static JSONObject normalized(JSONObject card)throws Exception{JSONObject copy=Card.from(card.toString()).json();if(copy.getInt("font")==3)copy.put("font",0);return copy;}
    static Set<String> refs(JSONObject card)throws JSONException{Set<String> refs=new TreeSet<>();String bg=card.getString("backgroundAsset");if(!bg.isEmpty())refs.add(bg);JSONArray stickers=card.getJSONArray("stickers");for(int n=0;n<stickers.length();n++)refs.add(stickers.getJSONObject(n).getString("asset"));return refs;}
    static String canonical(Object value)throws JSONException{
        if(value instanceof JSONObject){JSONObject j=(JSONObject)value;ArrayList<String> keys=new ArrayList<>();j.keys().forEachRemaining(keys::add);Collections.sort(keys);StringBuilder out=new StringBuilder("{");for(String k:keys){if(out.length()>1)out.append(',');out.append(JSONObject.quote(k)).append(':').append(canonical(j.get(k)));}return out.append('}').toString();}
        if(value instanceof JSONArray){JSONArray list=(JSONArray)value;StringBuilder out=new StringBuilder("[");for(int n=0;n<list.length();n++){if(n>0)out.append(',');out.append(canonical(list.get(n)));}return out.append(']').toString();}return value instanceof String?JSONObject.quote((String)value):String.valueOf(value);
    }
    static void collect(File file,String path,Map<String,File> files)throws IOException{if(!file.isFile())throw new IOException("缺少本地文件："+path);safe(path);require(file.length()<=(path.startsWith("photos/")?MAX_IMAGE:8L*1024*1024),"图片超过备份单文件限制");files.put(path,file);}
    static File export(Context c)throws Exception{
        File stage=temp(c);try{
            JSONArray cards=new JSONArray(),fonts=new JSONArray(),builtin=new JSONArray();Map<String,File> files=new TreeMap<>();Set<Integer> fontIds=new TreeSet<>();Set<String> builtins=new TreeSet<>();AssetStore library=new AssetStore(c);
            {for(Card card:new Store(c).all()){JSONObject j=normalized(card.json());validateCard(j);validateWater(j);cards.put(j);fontIds.add(j.getInt("font"));for(String key:new String[]{"photo","backgroundPhoto"}){String name=j.getString(key);if(!name.isEmpty())collect(new File(c.getFilesDir(),"photos/"+name),"photos/"+name,files);}for(String ref:refs(j))if(ref.startsWith("builtin:"))builtins.add(ref);}
                File[] singles=new File(c.getFilesDir(),"stickers").listFiles();if(singles!=null)for(File f:singles)if(f.getName().matches("[a-f0-9]{64}\\.png"))collect(f,"stickers/"+f.getName(),files);
                File[] packs=new File(c.getFilesDir(),"assetpacks").listFiles();if(packs!=null)for(File dir:packs)if(dir.isDirectory()&&dir.getName().matches("[a-f0-9]{64}")&&new File(dir,"manifest.json").isFile()&&!hidden(new File(dir,"manifest.json"))){JSONObject manifest=parse(new File(dir,"manifest.json"),128*1024);String prefix="assetpacks/"+dir.getName()+"/";collect(new File(dir,"manifest.json"),prefix+"manifest.json",files);for(AssetStore.Asset a:library.readManifest(manifest,dir,false))collect(a.file,prefix+dir.toPath().relativize(a.file.toPath()).toString().replace('\\','/'),files);}
                require(cards.length()<=MAX_CARDS,"卡片超过 500 张限制");json(new File(stage,"cards.json"),cards);files.put("cards.json",new File(stage,"cards.json"));
                for(int id:fontIds)fonts.put(new JSONObject().put("id",id).put("name",Card.FONTS[id]).put("sha256",FontCatalog.fingerprint(c,id)));
                for(String ref:builtins){AssetStore.Asset asset=library.get(ref);require(asset!=null,"内置素材已缺失："+ref);try(InputStream in=asset.open(c)){builtin.put(new JSONObject().put("ref",ref).put("sha256",hash(in)));}}
                JSONArray inventory=new JSONArray();long total=0;for(Map.Entry<String,File> entry:files.entrySet()){total+=entry.getValue().length();require(total<=MAX_TOTAL&&files.size()<=MAX_FILES,"备份超过容量或文件数量限制");inventory.put(new JSONObject().put("path",entry.getKey()).put("bytes",entry.getValue().length()).put("sha256",hash(entry.getValue())));}
                JSONObject metadata=new JSONObject().put("format",2).put("application",APP).put("appVersion","0.3.4-candidate").put("appVersionCode",7).put("createdAt",Instant.now().toString()).put("backupId",UUID.randomUUID().toString()).put("files",inventory).put("fonts",fonts).put("builtinAssets",builtin);json(new File(stage,"backup.json"),metadata);files.put("backup.json",new File(stage,"backup.json"));
                File archive=new File(stage,"CloudWidget-backup.zip");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(archive))){for(Map.Entry<String,File> entry:files.entrySet()){zip.putNextEntry(new ZipEntry(entry.getKey()));try(InputStream in=new FileInputStream(entry.getValue())){Io.copy(in,zip);}zip.closeEntry();}}
                try(InputStream in=new FileInputStream(archive);Plan checked=prepare(c,in)){/* full validation before any document write */}
                return archive;
            }
        }catch(Exception|OutOfMemoryError error){remove(stage);throw error;}
    }
    static Plan prepare(Context c,InputStream input)throws Exception{
        Plan plan=new Plan();plan.stage=temp(c);try{
            final long[] compressed={0};InputStream bounded=new FilterInputStream(input){@Override public int read(byte[] b,int o,int l)throws IOException{int n=super.read(b,o,l);if(n>0&&(compressed[0]+=n)>MAX_TOTAL)throw new IOException("压缩文件超过 256 MiB");return n;}@Override public int read()throws IOException{int n=super.read();if(n>=0&&++compressed[0]>MAX_TOTAL)throw new IOException("压缩文件超过 256 MiB");return n;}};
            long total=0;try(ZipInputStream zip=new ZipInputStream(bounded)){ZipEntry entry;int count=0;while((entry=zip.getNextEntry())!=null){require(++count<=MAX_FILES+1,"备份文件过多");String path=safe(entry.getName());require(!entry.isDirectory()&&!plan.files.containsKey(path),"备份路径重复或包含目录项");byte[] data=AssetStore.limited(zip,path.equals("cards.json")?4*1024*1024:path.equals("backup.json")?1024*1024:path.startsWith("photos/")?MAX_IMAGE:8L*1024*1024);total+=data.length;require(total<=MAX_TOTAL,"解压后超过 256 MiB");File file=new File(plan.stage,path);write(file,data);plan.files.put(path,file);}}
            require(plan.files.containsKey("backup.json")&&plan.files.containsKey("cards.json"),"缺少备份清单或卡片数据");plan.meta=parse(plan.files.get("backup.json"),1024*1024);JSONObject meta=plan.meta;Object formatValue=meta.opt("format");require(formatValue instanceof Number&&(((Number)formatValue).doubleValue()==1||((Number)formatValue).doubleValue()==2),"暂不支持此备份格式，请更新应用");int format=((Number)formatValue).intValue();require(APP.equals(meta.getString("application")),"不是云朵小卡备份");UUID.fromString(meta.getString("backupId"));Instant.parse(meta.getString("createdAt"));require(meta.getString("appVersion").length()<=80,"来源版本无效");plan.digest=hash(plan.files.get("backup.json"));
            Set<String> expected=new HashSet<>();expected.add("backup.json");JSONArray inventory=meta.getJSONArray("files");for(int n=0;n<inventory.length();n++){JSONObject j=inventory.getJSONObject(n);String path=safe(j.getString("path"));require(!path.equals("backup.json")&&expected.add(path),"清单路径重复");File file=plan.files.get(path);require(file!=null&&file.length()==j.getLong("bytes")&&hash(file).equals(j.getString("sha256")),"文件缺失、大小或哈希不符："+path);}require(expected.equals(plan.files.keySet()),"备份包含未登记文件");
            Set<String> declaredPackFiles=new HashSet<>();Map<String,String> assetPaths=new HashMap<>();AssetStore library=new AssetStore(c);Set<String> packRefs=new HashSet<>();for(String path:plan.files.keySet())if(path.startsWith("assetpacks/")&&path.endsWith("/manifest.json")){String prefix=path.substring(0,path.length()-13);File dir=plan.files.get(path).getParentFile();JSONObject manifest=parse(plan.files.get(path),128*1024);List<AssetStore.Asset> list=library.readManifest(manifest,dir,false);StringBuilder digest=new StringBuilder(manifest.toString());Set<String> members=new HashSet<>();members.add(path);for(AssetStore.Asset a:list){String asset=prefix+dir.toPath().relativize(a.file.toPath()).toString().replace('\\','/');File file=plan.files.get(asset);require(file!=null&&packRefs.add(a.ref),"素材包缺图或 ID/版本重复");digest.append(a.id).append(hash(file));assetPaths.put(a.ref,asset);members.add(asset);}require(AssetStore.hash(digest.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(dir.getName()),"素材包目录指纹不符");for(String candidate:plan.files.keySet())if(candidate.startsWith(prefix))require(members.contains(candidate),"素材包存在未登记图片");declaredPackFiles.addAll(members);plan.packs++;}
            for(Map.Entry<String,File> entry:plan.files.entrySet()){String path=entry.getKey();require(!path.startsWith("assetpacks/")||declaredPackFiles.contains(path),"存在未登记的素材包文件");if(path.endsWith(".png")){AssetStore.validatePng(bytes(entry.getValue(),MAX_IMAGE));if(path.startsWith("photos/"))plan.photos++;if(path.startsWith("stickers/")){String digest=hash(entry.getValue());require(path.equals("stickers/"+digest+".png"),"单张 PNG 指纹不符");assetPaths.put("png:"+digest,path);plan.pngs++;}}else require(path.equals("backup.json")||path.equals("cards.json")||(path.startsWith("assetpacks/")&&path.endsWith("/manifest.json")),"备份文件类型不受支持");}
            Set<Integer> availableFonts=new HashSet<>();JSONArray fonts=meta.getJSONArray("fonts");for(int n=0;n<fonts.length();n++){JSONObject f=fonts.getJSONObject(n);int id=f.getInt("id");require(id>=0&&id<Card.FONTS.length&&Card.FONTS[id].equals(f.getString("name"))&&(id==3?(f.getString("sha256").matches("[A-Fa-f0-9]{64}")||f.getString("sha256").equals("system-default")):FontCatalog.fingerprint(c,id).equals(f.getString("sha256")))&&availableFonts.add(id),"字体资源不匹配，请更新到对应应用版本");}
            Set<String> builtin=new HashSet<>();JSONArray assets=meta.getJSONArray("builtinAssets");for(int n=0;n<assets.length();n++){JSONObject a=assets.getJSONObject(n);String ref=a.getString("ref");AssetStore.Asset installed=library.get(ref);require(ref.startsWith("builtin:")&&installed!=null&&builtin.add(ref),"缺少内置素材，请更新应用："+ref);try(InputStream in=installed.open(c)){require(hash(in).equals(a.getString("sha256")),"内置素材版本不匹配："+ref);}}
            plan.cards=new JSONArray(new String(bytes(plan.files.get("cards.json"),4*1024*1024),java.nio.charset.StandardCharsets.UTF_8));require(plan.cards.length()<=MAX_CARDS,"卡片数量超过限制");Set<String> ids=new HashSet<>();for(int n=0;n<plan.cards.length();n++){JSONObject card=plan.cards.getJSONObject(n);require(card.optInt("schema")== (format==1?3:4),"卡片与备份格式版本不匹配");validateCard(card);validateWater(card);require(ids.add(card.getString("id")),"卡片 ID 重复");require(availableFonts.contains(card.getInt("font")),"缺少卡片字体声明");for(String key:new String[]{"photo","backgroundPhoto"}){String name=card.getString(key);require(name.isEmpty()||plan.files.containsKey("photos/"+name),"缺少卡片照片："+name);}for(String ref:refs(card))require(ref.startsWith("builtin:")?builtin.contains(ref):assetPaths.containsKey(ref),"缺少卡片素材："+ref);if(card.getInt("font")==3)plan.fontFallbackCards++;JSONObject mapped=normalized(card);plan.cards.put(n,mapped);String current=prefs(c).getString("card:"+card.getString("id"),null);if(current!=null&&!canonical(normalized(new JSONObject(current))).equals(canonical(mapped)))plan.conflicts++;}
            String previous=prefs(c).getString(RECEIPT+meta.getString("backupId"),null);if(previous!=null){require(previous.equals(plan.digest),"同一备份 ID 的内容已经改变，拒绝覆盖");plan.duplicate=true;}return plan;
        }catch(StackOverflowError error){plan.close();throw new IOException("备份结构过深，拒绝恢复",error);}catch(Exception|OutOfMemoryError error){plan.close();throw error;}
    }
    static AtomicFile journal(Context c){return new AtomicFile(new File(c.getFilesDir(),"restore-journal.json"));}
    static AtomicFile exportJournal(Context c){return new AtomicFile(new File(c.getFilesDir(),"export-journal.json"));}
    static void releaseDocument(Context c,Uri uri){try{for(UriPermission grant:c.getContentResolver().getPersistedUriPermissions())if(grant.getUri().equals(uri)){if(grant.isReadPermission())c.getContentResolver().releasePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);if(grant.isWritePermission())c.getContentResolver().releasePersistableUriPermission(uri,Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}}catch(Exception ignored){}}
    static void recoverExport(Context c)throws IOException{synchronized(EXPORT_LOCK){AtomicFile record=exportJournal(c);if(!record.getBaseFile().exists())return;try{
        JSONObject job;try(InputStream input=record.openRead()){job=new JSONObject(new String(AssetStore.limited(input,8192),java.nio.charset.StandardCharsets.UTF_8));}Uri uri=Uri.parse(job.getString("uri"));boolean complete=false;try(InputStream input=c.getContentResolver().openInputStream(uri)){complete=input!=null&&hash(input).equals(job.getString("sha256"));}catch(Exception ignored){}
        if(!complete){boolean removed;try{removed=DocumentsContract.deleteDocument(c.getContentResolver(),uri);}catch(FileNotFoundException missing){removed=true;}catch(Exception error){throw new IOException("上次导出未完成，无法清理所选文档："+uri,error);}require(removed,"上次导出未完成，请检查所选文档："+uri);}
        record.delete();releaseDocument(c,uri);
    }catch(JSONException error){throw new IOException("上次导出日志损坏，请检查备份保存位置",error);}}}
    static void exportDocument(Context c,File archive,Uri uri,Fault fault)throws Exception{synchronized(EXPORT_LOCK){
        require(!exportJournal(c).getBaseFile().exists(),"另一个导出尚未完成，请重新打开应用检查");AtomicFile record=exportJournal(c);FileOutputStream output=record.startWrite();try{output.write(new JSONObject().put("uri",uri.toString()).put("sha256",hash(archive)).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));record.finishWrite(output);}catch(Exception error){record.failWrite(output);throw error;}
        try{
            try(InputStream input=new FileInputStream(archive);OutputStream destination=c.getContentResolver().openOutputStream(uri,"w")){if(destination==null)throw new IOException("无法写入所选文档");byte[] bytes=new byte[16384];int n;boolean first=true;while((n=input.read(bytes))!=-1){destination.write(bytes,0,n);if(first){first=false;fault.at("export-first-write");}}destination.flush();}
            try(InputStream saved=c.getContentResolver().openInputStream(uri)){require(saved!=null&&hash(archive).equals(hash(saved)),"保存后备份哈希不符");}fault.at("export-after-verify");record.delete();releaseDocument(c,uri);
        }catch(Exception error){try{recoverExport(c);}catch(IOException cleanup){error.addSuppressed(cleanup);}throw error;}
    }}
    static void saveJournal(Context c,JSONObject value)throws IOException{AtomicFile journal=journal(c);FileOutputStream out=journal.startWrite();try{out.write(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));journal.finishWrite(out);}catch(IOException error){journal.failWrite(out);throw error;}}
    static boolean hidden(File file){synchronized(DataLock.LOCK){String absolute=file.getAbsolutePath();for(String path:pendingPaths)if(absolute.equals(path))return true;return false;}}
    static void recover(Context c)throws IOException{synchronized(DataLock.LOCK){AtomicFile journal=journal(c);if(!journal.getBaseFile().exists())return;try{JSONObject record;try(InputStream in=journal.openRead()){record=new JSONObject(new String(AssetStore.limited(in,1024*1024),java.nio.charset.StandardCharsets.UTF_8));}boolean committed=record.getString("token").equals(prefs(c).getString(MARKER,""));JSONArray files=record.getJSONArray("files");if(!committed)for(int n=0;n<files.length();n++){JSONObject entry=files.getJSONObject(n);File file=local(c,entry.getString("path"));if(file.isFile()&&hash(file).equals(entry.getString("sha256"))&&!file.delete())throw new IOException("未完成恢复的临时文件无法清理");File parent=file.getParentFile();while(parent!=null&&!parent.equals(c.getFilesDir())&&parent.isDirectory()){String[] children=parent.list();if(children==null||children.length!=0||!parent.delete())break;parent=parent.getParentFile();}}journal.delete();pendingPaths.clear();}catch(JSONException error){throw new IOException("恢复事务日志损坏，请保留数据并检查存储",error);}}}
    static void rewrite(JSONObject card,Map<String,String> photos,Map<String,String> refs)throws JSONException{for(String key:new String[]{"photo","backgroundPhoto"}){String old=card.getString(key);if(photos.containsKey(old))card.put(key,photos.get(old));}String bg=card.getString("backgroundAsset");if(refs.containsKey(bg))card.put("backgroundAsset",refs.get(bg));JSONArray stickers=card.getJSONArray("stickers");for(int n=0;n<stickers.length();n++){JSONObject sticker=stickers.getJSONObject(n);String old=sticker.getString("asset");if(refs.containsKey(old))sticker.put("asset",refs.get(old));}}
    static int apply(Context c,Plan plan,Fault fault)throws Exception{synchronized(DataLock.LOCK){
        recover(c);String receipt=RECEIPT+plan.meta.getString("backupId");String previous=prefs(c).getString(receipt,null);if(previous!=null){require(previous.equals(plan.digest),"同一备份 ID 内容冲突");return 0;}
        Map<String,String> photoNames=new HashMap<>(),refs=new HashMap<>();Map<String,File> additions=new TreeMap<>();AssetStore library=new AssetStore(c);
        for(Map.Entry<String,File> entry:plan.files.entrySet()){String path=entry.getKey();if(path.startsWith("photos/")){String name="restore-"+hash(entry.getValue())+".png";photoNames.put(path.substring(7),name);additions.put("photos/"+name,entry.getValue());}else if(path.startsWith("stickers/"))additions.put(path,entry.getValue());}
        for(String path:new ArrayList<>(plan.files.keySet()))if(path.startsWith("assetpacks/")&&path.endsWith("/manifest.json")){
            File manifestFile=plan.files.get(path),dir=manifestFile.getParentFile();JSONObject manifest=parse(manifestFile,128*1024);List<AssetStore.Asset> incoming=library.readManifest(manifest,dir,false);boolean conflict=false;File[] installedPacks=new File(c.getFilesDir(),"assetpacks").listFiles();
            if(installedPacks!=null)for(File installed:installedPacks){File mf=new File(installed,"manifest.json");if(!mf.isFile()||hidden(mf))continue;JSONObject current=parse(mf,128*1024);if(current.optString("id").equals(manifest.getString("id"))&&current.optString("version").equals(manifest.getString("version"))){
                if(!canonical(current).equals(canonical(manifest)))conflict=true;
                for(AssetStore.Asset asset:incoming){String relative=dir.toPath().relativize(asset.file.toPath()).toString();File oldFile=new File(installed,relative);if(!oldFile.isFile()||!hash(oldFile).equals(hash(asset.file)))conflict=true;}
            }}
            // Same stable pack reference may not steal an old card's image. Give the incoming pack a new ID.
            if(conflict){String original=manifest.getString("id"),base=original.substring(0,Math.min(45,original.length()));manifest.put("id",base+".restored."+UUID.randomUUID().toString().replace("-","").substring(0,16));manifest.put("restoredFromId",original);}
            List<AssetStore.Asset> renamed=library.readManifest(manifest,dir,false);StringBuilder fingerprint=new StringBuilder(manifest.toString());for(AssetStore.Asset asset:renamed)fingerprint.append(asset.id).append(hash(asset.file));String digest=AssetStore.hash(fingerprint.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));File rewritten=new File(plan.stage,"rewritten-"+digest+".json");json(rewritten,manifest);additions.put("assetpacks/"+digest+"/manifest.json",rewritten);
            for(int n=0;n<incoming.size();n++){AssetStore.Asset old=incoming.get(n),asset=renamed.get(n);refs.put(old.ref,asset.ref);additions.put("assetpacks/"+digest+"/"+dir.toPath().relativize(asset.file.toPath()).toString().replace('\\','/'),asset.file);}
        }
        SharedPreferences.Editor edit=prefs(c).edit();ArrayList<String> addedKeys=new ArrayList<>();int count=0;for(int n=0;n<plan.cards.length();n++){JSONObject incoming=new JSONObject(plan.cards.getJSONObject(n).toString());rewrite(incoming,photoNames,refs);String key="card:"+incoming.getString("id"),raw=prefs(c).getString(key,null);if(raw!=null&&canonical(normalized(new JSONObject(raw))).equals(canonical(incoming)))continue;if(raw!=null){incoming.put("id",UUID.randomUUID().toString());key="card:"+incoming.getString("id");}edit.putString(key,incoming.toString());addedKeys.add(key);count++;}
        JSONArray moves=new JSONArray();Map<String,File> fresh=new TreeMap<>();for(Map.Entry<String,File> entry:additions.entrySet()){File target=local(c,entry.getKey());if(target.exists()){require(target.isFile()&&hash(target).equals(hash(entry.getValue())),"本地同路径内容冲突，已保护原文件");continue;}fresh.put(entry.getKey(),entry.getValue());moves.put(new JSONObject().put("path",entry.getKey()).put("sha256",hash(entry.getValue())));}
        String token=UUID.randomUUID().toString();JSONObject transaction=new JSONObject().put("token",token).put("files",moves);fault.at("before-journal");saveJournal(c,transaction);pendingPaths.clear();for(String path:fresh.keySet())pendingPaths.add(local(c,path).getAbsolutePath());boolean uncertain=false;
        try{
            for(Map.Entry<String,File> entry:fresh.entrySet()){File target=local(c,entry.getKey()),parent=target.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("恢复写入失败，存储空间不足");if(!entry.getValue().renameTo(target))throw new IOException("恢复写入失败，原数据保留");fault.at("after-file");}
            fault.at("before-publish");edit.putString(receipt,plan.digest).putString(MARKER,token);if(!edit.commit()){uncertain=true;SharedPreferences.Editor reset=prefs(c).edit().remove(receipt).remove(MARKER);for(String key:addedKeys)reset.remove(key);reset.commit();throw new IOException("数据写入未确认，请重新打开应用以完成事务检查；原卡未覆盖");}
            fault.at("after-publish");journal(c).delete();pendingPaths.clear();return count;
        }catch(Exception error){if(!uncertain)recover(c);throw error;}
    }}
}
